CE,iBAAA,CACA,oBAAA,CACA,UAAA,CACA,WAAA,CACA,aAAA,CAEA,+BACE,SAAA,CACA,OAAA,CACA,QAAA,CAEA,+CACE,8BAAA,CAGF,sDACE,0BAAA,CACA,iCAAA,CAIJ,iCACE,iBAAA,CACA,cAAA,CACA,KAAA,CACA,MAAA,CACA,OAAA,CACA,QAAA,CACA,mCAAA,CACA,cAAA,CACA,kBAAA,CAEA,wCACE,iBAAA,CACA,UAAA,CACA,WAAA,CACA,UAAA,CACA,QAAA,CACA,UAAA,CACA,mEAAA,CACA,cAAA,CACA,iBAAA,CAKN,+BACE,YAAA,CACA,wBAAA,CACA,QAAA,CACA,iBAAA,CACA,yDAAA,CAGF,sBACE,gBAAA,CACA,WAAA,CACA,iBAAA,CACA,cAAA,CACA,cAAA,CACA,eAAA,CACA,wCACE,CAGF,4BACE,0BAAA,CAGF,kCACE,oCAAA,CACA,qCAAA,CACA,qCAAA,CACA,0CAAA,CAEA,wCACE,6DAAA,CAIJ,oCACE,wBAAA,CACA,qCAAA,CACA,qDAAA,CAEA,0CACE,uBAAA,CAMN,yBACE,+BACE,kBAAA,CAGF,+BACE,iBAAA,CAEA,kCACE,cAAA,CAIJ,6BACE,iBAAA,CAGF,4BACE,gBAAA,CACA,cAAA,CACA,OAAA,CAGF,8BACE,iBAAA,CAIF,4BACE,mCAAA,CAIF,8BACE,yBAAA,CAGF,mCACE,kBAAA,CAGF,+BACE,iBAAA,CAGF,8BACE,mBAAA,CAGF,iCACE,wBAAA,CAGF,8BACE,OAAA,CACA,eAAA,CAIF,yBACE,UAAA,CACA,WAAA,CAEA,sDACE,0BAAA,CAGF,wCACE,WAAA,CACA,UAAA,CAIJ,4BACE,YAAA,CAGF,+BACE,iBAAA,CACA,OAAA,CAIF,sBACE,MAAA,CACA,iBAAA,CAAA',sourcesContent:['
.preset-panel-overlay {
  /* 强调色跟随酒馆正文色: 亮主题为深色, 暗主题为浅色, 任何主题下都保证可读 */
  --theme-fg: var(--SmartThemeBodyColor, #888888);
  --accent: var(--theme-fg);
  --accent-strong: color-mix(in srgb, var(--theme-fg) 80%, transparent);
  --accent-soft: color-mix(in srgb, var(--theme-fg) 10%, transparent);
  --accent-border: color-mix(in srgb, var(--theme-fg) 35%, transparent);
  --accent-shadow: color-mix(in srgb, var(--theme-fg) 20%, transparent);
  /* 选中态用正文色低透明度填充, 文字始终保持正文色, 亮暗主题都不会糊成一片 */
  --accent-fill: color-mix(in srgb, var(--theme-fg) 16%, transparent);
  --accent-fill-strong: color-mix(in srgb, var(--theme-fg) 26%, transparent);
  /* 开关圆点取面板底色, 在填满的轨道上形成镂空效果 */
  --accent-on: var(--SmartThemeBlurTintColor, #1e1e1e);
  --bg-card: color-mix(in srgb, var(--theme-fg) 4%, transparent);
  --hover: color-mix(in srgb, var(--theme-fg) 8%, transparent);
  --line: color-mix(in srgb, var(--theme-fg) 16%, transparent);

  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  /* 移动端浏览器地址栏会改变可视高度: dvh 跟随实际可视区, 不支持时退回 100% */
  height: 100%;
  height: 100dvh;
  box-sizing: border-box;
  /* 预留刘海屏安全区, 保证标题栏和底部按钮始终可点 */
  padding: max(12px, env(safe-area-inset-top)) max(12px, env(safe-area-inset-right))
    max(12px, env(safe-area-inset-bottom)) max(12px, env(safe-area-inset-left));
  background: rgba(0, 0, 0, 0.55);
  backdrop-filter: blur(6px);
  display: flex;
  justify-content: center;
  /* 用 flex-start + 子元素 margin:auto 居中: 内容超高时不会像 align-items:center 那样把顶部裁掉 */
  align-items: flex-start;
  overflow-y: auto;
  overscroll-behavior: contain;
  z-index: 9999;
}

.preset-panel {
  background: var(--SmartThemeBlurTintColor, #1e1e1e);
  border: 1px solid var(--SmartThemeBorderColor, #454545);
  border-radius: 16px;
  box-sizing: border-box;
  width: 100%;
  max-width: 620px;
  /* 上限为遮罩可视高度, 超出部分交给 .panel-body 内部滚动, 面板不会溢出屏幕 */
  max-height: 100%;
  margin: auto;
  display: flex;
  flex-direction: column;
  box-shadow: 0 16px 48px rgba(0, 0, 0, 0.5);
  overflow: hidden;
}

.panel-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 14px 20px;
  border-bottom: 1px solid var(--SmartThemeBorderColor, #454545);
  background: linear-gradient(90deg, var(--accent-soft), transparent 60%);

  h2 {
    margin: 0;
    font-size: 16px;
    letter-spacing: 1px;
    color: var(--SmartThemeBodyColor, #fff);
  }

  .close-btn {
    background: none;
    border: none;
    color: var(--SmartThemeBodyColor, #fff);
    font-size: 18px;
    cursor: pointer;
    opacity: 0.6;
    transition:
      opacity 0.2s,
      transform 0.2s;

    &:hover {
      opacity: 1;
      transform: rotate(90deg);
    }
  }
}

.panel-body {
  flex: 1;
  overflow-y: auto;
  padding: 16px 20px;
}

.loading,
.error {
  text-align: center;
  padding: 40px;
  color: var(--SmartThemeBodyColor, #fff);
}

.error {
  color: #e8836f;
}

/* ── 顶部快捷区 ───────────────────────────── */
.quick-tabs {
  display: flex;
  gap: 4px;
  padding: 4px;
  margin-bottom: 12px;
  border-radius: 12px;
  background: var(--bg-card);
  border: 1px solid var(--SmartThemeBorderColor, #454545);
}

.quick-tab {
  flex: 1;
  min-width: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 9px 8px;
  border: none;
  border-radius: 9px;
  white-space: nowrap;
  background: transparent;
  color: var(--SmartThemeBodyColor, #fff);
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  opacity: 0.65;
  transition:
    background 0.2s,
    opacity 0.2s,
    color 0.2s;

  &:hover {
    opacity: 0.9;
  }

  &.active {
    background: var(--accent-fill);
    color: var(--SmartThemeBodyColor, #fff);
    opacity: 1;
    font-weight: 700;
    box-shadow:
      inset 0 0 0 1px var(--accent-border),
      0 1px 6px var(--accent-shadow);
  }
}

.quick-panel {
  margin-bottom: 16px;
  padding: 14px;
  border-radius: 12px;
  border: 1px dashed var(--accent-border);
  background: var(--accent-soft);
  display: flex;
  flex-direction: column;
  gap: 10px;
}

/* 场景按钮网格 */
.chip-list {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
}

.chip {
  padding: 10px 6px;
  border: 1px solid var(--SmartThemeBorderColor, #4f4f4f);
  border-radius: 10px;
  background: var(--bg-card);
  color: var(--SmartThemeBodyColor, #fff);
  font-size: 13px;
  cursor: pointer;
  transition:
    background 0.2s,
    border-color 0.2s,
    transform 0.15s;

  &:hover {
    background: var(--hover);
    transform: translateY(-1px);
  }

  &.active {
    background: var(--accent-fill-strong);
    border-color: var(--accent-border);
    color: var(--SmartThemeBodyColor, #fff);
    font-weight: 600;
    box-shadow: 0 1px 6px var(--accent-shadow);
  }
}

.hint {
  font-size: 12px;
  line-height: 1.6;
  color: var(--SmartThemeBodyColor, #fff);
  opacity: 0.55;
}

.ungrouped-hint {
  margin-bottom: 8px;
}

.warning {
  font-size: 12px;
  line-height: 1.6;
  color: #f0b67f;
  background: rgba(240, 182, 127, 0.12);
  border: 1px solid rgba(240, 182, 127, 0.35);
  border-radius: 8px;
  padding: 8px 12px;
  margin-bottom: 10px;
}

.config-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px 14px;
}

.config-row {
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-width: 0;
}

.config-label {
  font-size: 12px;
  color: var(--SmartThemeBodyColor, #fff);
  opacity: 0.65;
}

.config-select {
  width: 100%;
  min-width: 0;
  padding: 6px 10px;
  border: 1px solid var(--SmartThemeBorderColor, #4f4f4f);
  border-radius: 8px;
  background: var(--accent-soft);
  color: var(--SmartThemeBodyColor, #fff);
  font-size: 13px;
  outline: none;
  overflow: hidden;
  text-overflow: ellipsis;
  transition: border-color 0.2s;

  &:focus {
    border-color: var(--accent);
  }
}

.config-row--multi {
  grid-column: 1 / -1;
}

.config-checks {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.config-check {
  display: flex;
  align-items: center;
  gap: 5px;
  padding: 5px 10px;
  border: 1px solid var(--SmartThemeBorderColor, #4f4f4f);
  border-radius: 8px;
  background: var(--accent-soft);
  cursor: pointer;
  transition:
    background 0.2s,
    border-color 0.2s;

  &:hover {
    background: var(--hover);
  }

  &:has(input:checked) {
    background: var(--accent-fill);
    border-color: var(--accent-border);
  }

  input[type='checkbox'] {
    accent-color: var(--accent);
    width: 14px;
    height: 14px;
    margin: 0;
    cursor: pointer;
  }
}

.config-check-label {
  font-size: 12px;
  color: var(--SmartThemeBodyColor, #fff);
  white-space: nowrap;
}

.apply-config-btn {
  align-self: flex-end;
}

/* ── 分组 ───────────────────────────── */
.group-section {
  margin-bottom: 10px;
  border: 1px solid var(--SmartThemeBorderColor, #454545);
  border-radius: 10px;
  overflow: hidden;
  background: var(--bg-card);
}

.group-header {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 14px;
  cursor: pointer;
  user-select: none;
  border-left: 3px solid var(--accent);
  transition: background 0.2s;

  &:hover {
    background: var(--hover);
  }

  i {
    font-size: 11px;
    color: var(--accent);
    opacity: 0.9;
  }

  .group-name {
    flex: 1;
    font-weight: 600;
    font-size: 14px;
    color: var(--SmartThemeBodyColor, #fff);
  }

  .group-count {
    font-size: 11px;
    padding: 2px 8px;
    border-radius: 999px;
    background: var(--accent-fill);
    color: var(--SmartThemeBodyColor, #fff);
    opacity: 0.7;
  }
}

.group-items {
  padding: 6px 10px 8px;
}

.subgroup-section {
  margin: 4px 0;
  border: 1px solid var(--SmartThemeBorderColor, #454545);
  border-radius: 8px;
  overflow: hidden;
}

.subgroup-header {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 12px;
  background: var(--bg-card);
  cursor: pointer;
  user-select: none;

  &:hover {
    background: var(--hover);
  }

  i {
    font-size: 9px;
    color: var(--SmartThemeBodyColor, #fff);
    opacity: 0.5;
  }

  .subgroup-name {
    flex: 1;
    font-size: 12px;
    font-weight: 500;
    color: var(--SmartThemeBodyColor, #fff);
    opacity: 0.85;
  }
}

.subgroup-items {
  padding: 4px 4px 4px 16px;
}

.prompt-item {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 7px 8px;
  border-radius: 8px;
  margin-bottom: 2px;

  &:hover {
    background: var(--hover);
  }

  &.is-marker {
    opacity: 0.55;
    font-style: italic;

    .item-name {
      color: var(--accent);
    }
  }

  &.is-locked {
    .switch {
      cursor: not-allowed;
      opacity: 0.4;

      .slider {
        cursor: not-allowed;
      }
    }

    .item-name {
      opacity: 0.7;
    }
  }
}

.item-name {
  flex: 1;
  color: var(--SmartThemeBodyColor, #fff);
  font-size: 13px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.item-role {
  font-size: 10px;
  color: var(--SmartThemeBodyColor, #fff);
  opacity: 0.35;
  text-transform: uppercase;
  letter-spacing: 1px;
}

/* Switch 开关 */
.switch {
  position: relative;
  display: inline-block;
  width: 38px;
  height: 22px;
  flex-shrink: 0;

  input {
    opacity: 0;
    width: 0;
    height: 0;

    &:checked + .slider {
      background-color: var(--accent);
    }

    &:checked + .slider:before {
      transform: translateX(16px);
      background-color: var(--accent-on);
    }
  }

  .slider {
    position: absolute;
    cursor: pointer;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background-color: var(--accent-fill);
    transition: 0.2s;
    border-radius: 22px;

    &:before {
      position: absolute;
      content: '';
      height: 16px;
      width: 16px;
      left: 3px;
      bottom: 3px;
      background-color: color-mix(in srgb, var(--theme-fg) 45%, transparent);
      transition: 0.2s;
      border-radius: 50%;
    }
  }
}

.panel-footer {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
  padding: 14px 20px;
  border-top: 1px solid var(--SmartThemeBorderColor, #454545);
}

.btn {
  padding: 8px 18px;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  font-size: 13px;
  font-weight: 600;
  transition:
    background 0.2s,
    transform 0.15s;

  &:hover {
    transform: translateY(-1px);
  }

  &.btn-primary {
    background: var(--accent-fill-strong);
    color: var(--SmartThemeBodyColor, #fff);
    border: 1px solid var(--accent-border);
    box-shadow: 0 2px 10px var(--accent-shadow);

    &:hover {
      background: color-mix(in srgb, var(--theme-fg) 36%, transparent);
    }
  }

  &.btn-secondary {
    background: transparent;
    color: var(--SmartThemeBodyColor, #fff);
    border: 1px solid var(--SmartThemeBorderColor, #4f4f4f);

    &:hover {
      background: var(--hover);
    }
  }
}

/* ── 移动端适配 ───────────────────────────── */
@media (max-width: 768px) {
  .preset-panel {
    border-radius: 12px;
  }

  .panel-header {
    padding: 12px 14px;

    h2 {
      font-size: 15px;
    }
  }

  .panel-body {
    padding: 12px 12px;
  }

  .quick-tab {
    padding: 10px 4px;
    font-size: 12px;
    gap: 4px;
  }

  .quick-panel {
    padding: 12px 10px;
  }

  /* 窄屏下三列会把场景名挤成竖排, 改两列 */
  .chip-list {
    grid-template-columns: repeat(2, 1fr);
  }

  /* 下拉框单列排布, 避免选项文字被截断 */
  .config-grid {
    grid-template-columns: 1fr;
  }

  .apply-config-btn {
    align-self: stretch;
  }

  .group-header {
    padding: 10px 10px;
  }

  .group-items {
    padding: 6px 6px 8px;
  }

  .subgroup-items {
    padding: 4px 2px 4px 10px;
  }

  .prompt-item {
    gap: 8px;
    padding: 8px 6px;
  }

  /* 触摸目标保持够大, 同时给条目名留出宽度 */
  .switch {
    width: 42px;
    height: 24px;

    input:checked + .slider:before {
      transform: translateX(18px);
    }

    .slider:before {
      height: 18px;
      width: 18px;
    }
  }

  .item-role {
    display: none;
  }

  .panel-footer {
    padding: 12px 12px;
    gap: 8px;
  }

  /* 底部按钮平分宽度, 单手也能点到 */
  .btn {
    flex: 1;
    padding: 11px 10px;
  }
}
